-- Module 17: invoices, immutable payment allocations, AR aging, and accounting outbox.
insert into public.permissions(key,domain,action,description) values
('invoices.read','invoices','read','View invoices and receivables'),
('invoices.manage','invoices','manage','Create, issue, and cancel invoices'),
('invoices.payments','invoices','payments','Record and allocate customer payments')
on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_invoice_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager','staff')and permission.key in('invoices.read','invoices.manage','invoices.payments')on conflict do nothing;end;$$;
create function private.handle_main_branch_invoice_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_invoice_permissions(new.organization_id);end if;return new;end;$$;create trigger zzzzzzzzzz_install_invoice_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_invoice_permissions();select private.install_invoice_permissions(id)from public.organizations;

create table public.invoice_number_counters(organization_id uuid not null references public.organizations(id)on delete cascade,year integer not null,last_number integer not null default 0,primary key(organization_id,year));
create table public.payment_number_counters(organization_id uuid not null references public.organizations(id)on delete cascade,year integer not null,last_number integer not null default 0,primary key(organization_id,year));
create table public.invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,branch_id uuid not null,invoice_number text not null,customer_id uuid not null,status text not null default'draft'check(status in('draft','issued','partially_paid','paid','overdue','cancelled')),invoice_date date not null,due_date date not null,credit_terms_days integer not null default 0 check(credit_terms_days between 0 and 3650),source_type text not null default'manual'check(source_type in('manual','sale','quotation','sales_order')),source_id uuid,notes text check(char_length(notes)<=4000),subtotal numeric(16,4)not null default 0 check(subtotal>=0),discount_total numeric(16,4)not null default 0 check(discount_total>=0),tax_total numeric(16,4)not null default 0 check(tax_total>=0),total numeric(16,4)not null default 0 check(total>=0),amount_paid numeric(16,4)not null default 0 check(amount_paid>=0),balance_due numeric(16,4)not null default 0 check(balance_due>=0),created_by uuid not null references auth.users(id),issued_at timestamptz,cancelled_at timestamptz,cancellation_reason text check(char_length(cancellation_reason)<=500),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,invoice_number),foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete restrict,check(due_date>=invoice_date),check(amount_paid<=total),check(balance_due<=total));
create unique index invoices_source_unique on public.invoices(organization_id,source_type,source_id)where source_id is not null and status<>'cancelled';
create table public.invoice_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,invoice_id uuid not null,description text not null check(char_length(btrim(description))between 1 and 500),product_variant_id uuid,sku text,unit text not null,quantity numeric(16,4)not null check(quantity>0),unit_price numeric(16,4)not null check(unit_price>=0),discount_amount numeric(16,4)not null default 0 check(discount_amount>=0),tax_rate numeric(7,4)not null default 0 check(tax_rate between 0 and 100),subtotal numeric(16,4)not null,tax_amount numeric(16,4)not null,total numeric(16,4)not null,position integer not null,unique(invoice_id,position),foreign key(invoice_id,organization_id)references public.invoices(id,organization_id)on delete cascade,foreign key(product_variant_id,organization_id)references public.product_variants(id,organization_id)on delete restrict);
create table public.ar_payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,branch_id uuid not null,payment_number text not null,customer_id uuid not null,payment_date date not null,payment_method text not null check(payment_method in('cash','bank_transfer','card','digital_wallet','cheque','other')),reference text check(char_length(reference)<=160),amount numeric(16,4)not null check(amount>0),unapplied_amount numeric(16,4)not null check(unapplied_amount>=0 and unapplied_amount<=amount),idempotency_key text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,payment_number),unique(organization_id,idempotency_key),foreign key(branch_id,organization_id)references public.branches(id,organization_id),foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id));
create table public.payment_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,payment_id uuid not null,invoice_id uuid not null,amount numeric(16,4)not null check(amount>0),allocated_by uuid not null references auth.users(id),allocated_at timestamptz not null default now(),unique(payment_id,invoice_id),foreign key(payment_id,organization_id)references public.ar_payments(id,organization_id)on delete restrict,foreign key(invoice_id,organization_id)references public.invoices(id,organization_id)on delete restrict);
create table public.invoice_audit_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null,invoice_id uuid not null,event text not null,actor_id uuid not null references auth.users(id),details jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(invoice_id,organization_id)references public.invoices(id,organization_id)on delete cascade);
create table public.accounting_integration_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,event_key text not null,event_type text not null,aggregate_type text not null,aggregate_id uuid not null,payload jsonb not null,processing_status text not null default'pending'check(processing_status in('pending','processing','processed','failed')),attempt_count integer not null default 0,last_error text,created_at timestamptz not null default now(),processed_at timestamptz,unique(organization_id,event_key));
create index invoices_ar_list_idx on public.invoices(organization_id,branch_id,status,due_date)where status in('issued','partially_paid','overdue');create index invoices_customer_idx on public.invoices(customer_id,created_at desc);create index invoice_lines_invoice_idx on public.invoice_lines(invoice_id,position);create index ar_payments_customer_idx on public.ar_payments(customer_id,payment_date desc);create index payment_allocations_invoice_idx on public.payment_allocations(invoice_id,allocated_at);create index invoice_audit_invoice_idx on public.invoice_audit_history(invoice_id,created_at);create index accounting_events_pending_idx on public.accounting_integration_events(created_at)where processing_status in('pending','failed');
create trigger set_updated_at before update on public.invoices for each row execute function private.set_updated_at();

create function private.invoicing_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='invoicing');$$;
alter table public.invoice_number_counters enable row level security;alter table public.payment_number_counters enable row level security;alter table public.invoices enable row level security;alter table public.invoice_lines enable row level security;alter table public.ar_payments enable row level security;alter table public.payment_allocations enable row level security;alter table public.invoice_audit_history enable row level security;alter table public.accounting_integration_events enable row level security;
create policy invoices_read on public.invoices for select to authenticated using((select private.invoicing_module_enabled(organization_id))and private.can_business_permission(organization_id,'invoices.read',branch_id));
create policy invoice_lines_read on public.invoice_lines for select to authenticated using(exists(select 1 from public.invoices invoice where invoice.id=invoice_lines.invoice_id and invoice.organization_id=invoice_lines.organization_id and private.can_business_permission(invoice.organization_id,'invoices.read',invoice.branch_id)));
create policy ar_payments_read on public.ar_payments for select to authenticated using((select private.invoicing_module_enabled(organization_id))and private.can_business_permission(organization_id,'invoices.read',branch_id));
create policy payment_allocations_read on public.payment_allocations for select to authenticated using(exists(select 1 from public.invoices invoice where invoice.id=payment_allocations.invoice_id and invoice.organization_id=payment_allocations.organization_id and private.can_business_permission(invoice.organization_id,'invoices.read',invoice.branch_id)));
create policy invoice_audit_read on public.invoice_audit_history for select to authenticated using(exists(select 1 from public.invoices invoice where invoice.id=invoice_audit_history.invoice_id and invoice.organization_id=invoice_audit_history.organization_id and private.can_business_permission(invoice.organization_id,'invoices.read',invoice.branch_id)));
revoke all on public.invoice_number_counters,public.payment_number_counters,public.invoices,public.invoice_lines,public.ar_payments,public.payment_allocations,public.invoice_audit_history,public.accounting_integration_events from public,anon,authenticated;grant select on public.invoices,public.invoice_lines,public.ar_payments,public.payment_allocations,public.invoice_audit_history to authenticated;

create function private.next_document_number(requested_organization_id uuid,requested_kind text)returns text language plpgsql security definer set search_path='' as $$declare current_year integer:=extract(year from current_date);next_number integer;begin if requested_kind='invoice'then insert into public.invoice_number_counters(organization_id,year,last_number)values(requested_organization_id,current_year,1)on conflict(organization_id,year)do update set last_number=public.invoice_number_counters.last_number+1 returning last_number into next_number;return'INV-'||current_year||'-'||lpad(next_number::text,6,'0');elsif requested_kind='payment'then insert into public.payment_number_counters(organization_id,year,last_number)values(requested_organization_id,current_year,1)on conflict(organization_id,year)do update set last_number=public.payment_number_counters.last_number+1 returning last_number into next_number;return'PAY-'||current_year||'-'||lpad(next_number::text,6,'0');end if;raise exception'Invalid document kind.'using errcode='22023';end;$$;
create function private.recompute_customer_receivable(requested_organization_id uuid,requested_customer_id uuid)returns void language sql security definer set search_path='' as $$update public.sales_customers set outstanding_balance=coalesce((select sum(balance_due)from public.invoices where organization_id=requested_organization_id and customer_id=requested_customer_id and status in('issued','partially_paid','overdue')),0)where id=requested_customer_id and organization_id=requested_organization_id;$$;
create function private.emit_accounting_event(requested_organization_id uuid,requested_event_key text,requested_event_type text,requested_aggregate_type text,requested_aggregate_id uuid,requested_payload jsonb)returns void language sql security definer set search_path='' as $$insert into public.accounting_integration_events(organization_id,event_key,event_type,aggregate_type,aggregate_id,payload)values(requested_organization_id,requested_event_key,requested_event_type,requested_aggregate_type,requested_aggregate_id,requested_payload)on conflict(organization_id,event_key)do nothing;$$;
create function private.save_invoice(requested_organization_id uuid,requested_invoice_id uuid,requested_branch_id uuid,requested_customer_id uuid,requested_invoice_date date,requested_due_date date,requested_notes text,requested_lines jsonb,requested_issue boolean)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_invoice_id,gen_random_uuid());actor uuid:=(select auth.uid());invoice public.invoices%rowtype;item jsonb;qty numeric;price numeric;discount numeric;tax_rate_value numeric;line_subtotal numeric;line_tax numeric;line_total numeric;subtotal_sum numeric:=0;discount_sum numeric:=0;tax_sum numeric:=0;total_sum numeric:=0;position_value integer:=0;invoice_number text;begin
 if actor is null or not private.invoicing_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'invoices.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_due_date<requested_invoice_date or jsonb_typeof(requested_lines)<>'array'or jsonb_array_length(requested_lines)not between 1 and 500 or char_length(coalesce(requested_notes,''))>4000 or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id and is_active)or not exists(select 1 from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id)then raise exception'Invalid invoice.'using errcode='22023';end if;
 if requested_invoice_id is not null then select*into invoice from public.invoices where id=target_id and organization_id=requested_organization_id for update;if invoice.id is null or invoice.status<>'draft'then raise exception'Only a draft invoice can be changed.'using errcode='P0001';end if;invoice_number:=invoice.invoice_number;delete from public.invoice_lines where invoice_id=target_id;else invoice_number:=private.next_document_number(requested_organization_id,'invoice');insert into public.invoices(id,organization_id,branch_id,invoice_number,customer_id,invoice_date,due_date,credit_terms_days,notes,created_by)values(target_id,requested_organization_id,requested_branch_id,invoice_number,requested_customer_id,requested_invoice_date,requested_due_date,requested_due_date-requested_invoice_date,nullif(btrim(requested_notes),''),actor);end if;
 for item in select value from jsonb_array_elements(requested_lines)loop if item-array['description','productVariantId','sku','unit','quantity','unitPrice','discountAmount','taxRate']::text[]<>'{}'::jsonb or not(item?&array['description','unit','quantity','unitPrice','discountAmount','taxRate'])then raise exception'Invalid invoice line.'using errcode='22023';end if;qty:=(item->>'quantity')::numeric;price:=(item->>'unitPrice')::numeric;discount:=(item->>'discountAmount')::numeric;tax_rate_value:=(item->>'taxRate')::numeric;line_subtotal:=round(qty*price,4);if char_length(btrim(item->>'description'))not between 1 and 500 or qty<=0 or price<0 or discount<0 or discount>line_subtotal or tax_rate_value<0 or tax_rate_value>100 or(nullif(item->>'productVariantId','')is not null and not exists(select 1 from public.product_variants where id=(item->>'productVariantId')::uuid and organization_id=requested_organization_id))then raise exception'Invalid invoice line.'using errcode='22023';end if;line_tax:=round((line_subtotal-discount)*tax_rate_value/100,4);line_total:=line_subtotal-discount+line_tax;insert into public.invoice_lines(organization_id,invoice_id,description,product_variant_id,sku,unit,quantity,unit_price,discount_amount,tax_rate,subtotal,tax_amount,total,position)values(requested_organization_id,target_id,btrim(item->>'description'),case when nullif(item->>'productVariantId','')is not null then(item->>'productVariantId')::uuid end,nullif(btrim(item->>'sku'),''),btrim(item->>'unit'),qty,price,discount,tax_rate_value,line_subtotal,line_tax,line_total,position_value);position_value:=position_value+1;subtotal_sum:=subtotal_sum+line_subtotal;discount_sum:=discount_sum+discount;tax_sum:=tax_sum+line_tax;total_sum:=total_sum+line_total;end loop;
 update public.invoices set branch_id=requested_branch_id,customer_id=requested_customer_id,invoice_date=requested_invoice_date,due_date=requested_due_date,credit_terms_days=requested_due_date-requested_invoice_date,notes=nullif(btrim(requested_notes),''),subtotal=subtotal_sum,discount_total=discount_sum,tax_total=tax_sum,total=total_sum,balance_due=case when requested_issue then total_sum else 0 end,status=case when requested_issue then'issued'else'draft'end,issued_at=case when requested_issue then now()end where id=target_id;insert into public.invoice_audit_history(organization_id,invoice_id,event,actor_id,details)values(requested_organization_id,target_id,case when requested_issue then'issued'when requested_invoice_id is null then'created'else'updated'end,actor,jsonb_build_object('total',total_sum,'lineCount',position_value));if requested_issue then perform private.recompute_customer_receivable(requested_organization_id,requested_customer_id);perform private.emit_accounting_event(requested_organization_id,'invoice:issued:'||target_id,'invoice.issued','invoice',target_id,jsonb_build_object('invoiceNumber',invoice_number,'customerId',requested_customer_id,'invoiceDate',requested_invoice_date,'dueDate',requested_due_date,'total',total_sum,'tax',tax_sum));end if;return target_id;exception when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid invoice data.'using errcode='22023';end;$$;
create function private.create_invoice_from_sale(requested_organization_id uuid,requested_sale_id uuid,requested_due_date date,requested_issue boolean)returns uuid language plpgsql security definer set search_path='' as $$declare sale public.sales_transactions%rowtype;lines jsonb;actor uuid:=(select auth.uid());target_id uuid;begin select*into sale from public.sales_transactions where id=requested_sale_id and organization_id=requested_organization_id;if actor is null or sale.id is null or sale.customer_id is null or sale.status not in('suspended','completed','partially_returned','returned')then raise exception'Sale cannot be invoiced.'using errcode='22023';end if;select jsonb_agg(jsonb_build_object('description',product_name||case when variant_name<>'Default'then' - '||variant_name else''end,'productVariantId',product_variant_id,'sku',sku,'unit','piece','quantity',quantity,'unitPrice',unit_price,'discountAmount',discount_amount,'taxRate',0)order by id)into lines from public.sales_lines where sale_id=sale.id;target_id:=private.save_invoice(requested_organization_id,null,sale.branch_id,sale.customer_id,current_date,requested_due_date,'Generated from sale '||sale.receipt_number,lines,false);with source_lines as(select line.*,row_number()over(order by id)-1 position from public.sales_lines line where sale_id=sale.id)update public.invoice_lines target set tax_amount=source.tax_amount,total=source.total from source_lines source where target.invoice_id=target_id and target.position=source.position;update public.invoices set source_type='sale',source_id=sale.id,subtotal=sale.subtotal,discount_total=sale.discount_total,tax_total=sale.tax_total,total=sale.total,status=case when requested_issue then'issued'else'draft'end,balance_due=case when requested_issue then sale.total else 0 end,issued_at=case when requested_issue then now()end where id=target_id;if requested_issue then insert into public.invoice_audit_history(organization_id,invoice_id,event,actor_id,details)values(requested_organization_id,target_id,'issued',actor,jsonb_build_object('total',sale.total,'sourceSaleId',sale.id));perform private.recompute_customer_receivable(requested_organization_id,sale.customer_id);perform private.emit_accounting_event(requested_organization_id,'invoice:issued:'||target_id,'invoice.issued','invoice',target_id,jsonb_build_object('invoiceNumber',(select invoice_number from public.invoices where id=target_id),'customerId',sale.customer_id,'invoiceDate',current_date,'dueDate',requested_due_date,'total',sale.total,'tax',sale.tax_total,'sourceSaleId',sale.id));end if;return target_id;end;$$;
create function private.record_ar_payment(requested_organization_id uuid,requested_branch_id uuid,requested_customer_id uuid,requested_payment_date date,requested_method text,requested_reference text,requested_amount numeric,requested_allocations jsonb,requested_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid;actor uuid:=(select auth.uid());item jsonb;invoice public.invoices%rowtype;allocation_sum numeric:=0;allocation_amount numeric;payment_number text;begin select id into target_id from public.ar_payments where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if found then return target_id;end if;target_id:=gen_random_uuid();if actor is null or not private.invoicing_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'invoices.payments',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_method not in('cash','bank_transfer','card','digital_wallet','cheque','other')or requested_amount<=0 or jsonb_typeof(requested_allocations)<>'array'or jsonb_array_length(requested_allocations)>100 or char_length(btrim(requested_idempotency_key))not between 8 and 200 then raise exception'Invalid payment.'using errcode='22023';end if;for item in select value from jsonb_array_elements(requested_allocations)order by value->>'invoiceId'loop if item-array['invoiceId','amount']::text[]<>'{}'::jsonb or not(item?&array['invoiceId','amount'])then raise exception'Invalid allocation.'using errcode='22023';end if;select*into invoice from public.invoices where id=(item->>'invoiceId')::uuid and organization_id=requested_organization_id for update;allocation_amount:=(item->>'amount')::numeric;if invoice.id is null or invoice.branch_id<>requested_branch_id or invoice.customer_id<>requested_customer_id or invoice.status not in('issued','partially_paid','overdue')or allocation_amount<=0 or allocation_amount>invoice.balance_due then raise exception'Invalid payment allocation.'using errcode='P0001';end if;allocation_sum:=allocation_sum+allocation_amount;end loop;if allocation_sum>requested_amount then raise exception'Allocations exceed payment amount.'using errcode='P0001';end if;payment_number:=private.next_document_number(requested_organization_id,'payment');insert into public.ar_payments(id,organization_id,branch_id,payment_number,customer_id,payment_date,payment_method,reference,amount,unapplied_amount,idempotency_key,created_by)values(target_id,requested_organization_id,requested_branch_id,payment_number,requested_customer_id,requested_payment_date,requested_method,nullif(btrim(requested_reference),''),requested_amount,requested_amount-allocation_sum,requested_idempotency_key,actor);for item in select value from jsonb_array_elements(requested_allocations)order by value->>'invoiceId'loop allocation_amount:=(item->>'amount')::numeric;insert into public.payment_allocations(organization_id,payment_id,invoice_id,amount,allocated_by)values(requested_organization_id,target_id,(item->>'invoiceId')::uuid,allocation_amount,actor);update public.invoices set amount_paid=amount_paid+allocation_amount,balance_due=balance_due-allocation_amount,status=case when balance_due-allocation_amount=0 then'paid'else'partially_paid'end where id=(item->>'invoiceId')::uuid;insert into public.invoice_audit_history(organization_id,invoice_id,event,actor_id,details)values(requested_organization_id,(item->>'invoiceId')::uuid,'payment_allocated',actor,jsonb_build_object('paymentId',target_id,'amount',allocation_amount));end loop;perform private.recompute_customer_receivable(requested_organization_id,requested_customer_id);perform private.emit_accounting_event(requested_organization_id,'payment:recorded:'||target_id,'payment.recorded','payment',target_id,jsonb_build_object('paymentNumber',payment_number,'customerId',requested_customer_id,'amount',requested_amount,'allocatedAmount',allocation_sum,'unappliedAmount',requested_amount-allocation_sum));return target_id;exception when unique_violation then select id into target_id from public.ar_payments where organization_id=requested_organization_id and idempotency_key=requested_idempotency_key;if target_id is null then raise;end if;return target_id;when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid payment data.'using errcode='22023';end;$$;
create function private.cancel_invoice(requested_organization_id uuid,requested_invoice_id uuid,requested_reason text)returns void language plpgsql security definer set search_path='' as $$declare invoice public.invoices%rowtype;actor uuid:=(select auth.uid());begin select*into invoice from public.invoices where id=requested_invoice_id and organization_id=requested_organization_id for update;if actor is null or invoice.id is null or not private.can_business_permission(requested_organization_id,'invoices.manage',invoice.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if invoice.status not in('draft','issued','overdue')or invoice.amount_paid>0 or char_length(btrim(requested_reason))not between 1 and 500 then raise exception'Invoice cannot be cancelled.'using errcode='P0001';end if;update public.invoices set status='cancelled',balance_due=0,cancelled_at=now(),cancellation_reason=btrim(requested_reason)where id=invoice.id;insert into public.invoice_audit_history(organization_id,invoice_id,event,actor_id,details)values(requested_organization_id,invoice.id,'cancelled',actor,jsonb_build_object('reason',requested_reason));perform private.recompute_customer_receivable(requested_organization_id,invoice.customer_id);perform private.emit_accounting_event(requested_organization_id,'invoice:cancelled:'||invoice.id,'invoice.cancelled','invoice',invoice.id,jsonb_build_object('invoiceNumber',invoice.invoice_number,'total',invoice.total));end;$$;
create function private.refresh_overdue_invoices(requested_organization_id uuid)returns integer language plpgsql security definer set search_path='' as $$declare affected integer;begin if(select auth.uid())is null or not private.invoicing_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'invoices.read',null)then raise exception'Permission denied.'using errcode='42501';end if;update public.invoices set status='overdue'where organization_id=requested_organization_id and status in('issued','partially_paid')and balance_due>0 and due_date<current_date;get diagnostics affected=row_count;return affected;end;$$;
create function public.receivables_dashboard(requested_organization_id uuid,requested_as_of date default current_date)returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if(select auth.uid())is null or not private.invoicing_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'invoices.read',null)then raise exception'Permission denied.'using errcode='42501';end if;with open_invoices as(select invoice.*,greatest(0,requested_as_of-invoice.due_date)age_days from public.invoices invoice where invoice.organization_id=requested_organization_id and invoice.status in('issued','partially_paid','overdue')and invoice.balance_due>0),buckets as(select case when age_days=0 then'current'when age_days between 1 and 30 then'1-30'when age_days between 31 and 60 then'31-60'when age_days between 61 and 90 then'61-90'else'90+'end bucket,balance_due from open_invoices),debtors as(select customer.id,customer.name,sum(invoice.balance_due)amount from open_invoices invoice join public.sales_customers customer on customer.id=invoice.customer_id group by customer.id,customer.name order by amount desc limit 10)select jsonb_build_object('totalReceivables',coalesce((select sum(balance_due)from open_invoices),0),'overdueAmount',coalesce((select sum(balance_due)from open_invoices where age_days>0),0),'aging',jsonb_build_object('current',coalesce((select sum(balance_due)from buckets where bucket='current'),0),'1-30',coalesce((select sum(balance_due)from buckets where bucket='1-30'),0),'31-60',coalesce((select sum(balance_due)from buckets where bucket='31-60'),0),'61-90',coalesce((select sum(balance_due)from buckets where bucket='61-90'),0),'90+',coalesce((select sum(balance_due)from buckets where bucket='90+'),0)),'topDebtors',coalesce((select jsonb_agg(jsonb_build_object('customerId',id,'customerName',name,'amount',amount))from debtors),'[]'))into result;return result;end;$$;

