revoke all on function private.install_invoice_permissions(uuid),private.handle_main_branch_invoice_permissions(),private.invoicing_module_enabled(uuid),private.next_document_number(uuid,text),private.recompute_customer_receivable(uuid,uuid),private.emit_accounting_event(uuid,text,text,text,uuid,jsonb),private.save_invoice(uuid,uuid,uuid,uuid,date,date,text,jsonb,boolean),private.create_invoice_from_sale(uuid,uuid,date,boolean),private.record_ar_payment(uuid,uuid,uuid,date,text,text,numeric,jsonb,text),private.cancel_invoice(uuid,uuid,text),private.refresh_overdue_invoices(uuid)from public,anon,authenticated;grant execute on function private.invoicing_module_enabled(uuid)to authenticated;
