create function private.reject_receivables_history_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception'Receivables history is immutable.'using errcode='42501';end;$$;create trigger allocations_immutable before update or delete on public.payment_allocations for each row execute function private.reject_receivables_history_mutation();create trigger invoice_audit_immutable before update or delete on public.invoice_audit_history for each row execute function private.reject_receivables_history_mutation();revoke all on function private.reject_receivables_history_mutation()from public,anon,authenticated;

